  var c = this;
};

sp_widget.css:
/* Header Section */
.custom-header {
  width: 100%;
  background: linear-gradient(to right, #1e3a8a, #2563eb); /* blue gradient */
  color: white;
  padding: 40px;
  overflow: hidden;
  border-bottom-left-radius: 40px;  /* curved edges */
  border-bottom-right-radius: 40px;
  border-top-left-radius: 40px;  /* curved edges */
  border-top-right-radius: 40px;
}

.header-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-text h1 {
  font-size: 2.5em;
  margin: 0;
}

.header-text p {
  font-size: 1.2em;
  margin-top: 8px;
  color: #ddd;
}

.header-graphic {
  display: flex;
  align-items: flex-end;
  gap: 12px;
}

.shape {
  background-color: #888;
  border-radius: 4px;
  position: relative;
  animation: float 3s ease-in-out infinite;
}

.shape1 {
  width: 40px;
  height: 60px;
  background-color: #9ca3af;
  animation-delay: 0s;
}
.shape2 {
  width: 50px;
  height: 80px;
  background-color: #6b7280;
  animation-delay: 0.5s;
}
.shape3 {
  width: 30px;
  height: 50px;
  background-color: #9ca3af;
  animation-delay: 1s;
}

/* Decorative Circles */
.shape1::before,
.shape2::before,
.shape3::before {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  animation: pulse 2s infinite ease-in-out;
}
.shape1::before { background-color: #38bdf8; } /* light blue */
.shape2::before { background-color: #93c5fd; } /* softer blue */
.shape3::before { background-color: #60a5fa; } /* medium blue */

/* Floating Animation */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}
@keyframes pulse {
  0%, 100% { transform: translateX(-50%) scale(1); opacity: 1; }
  50% { transform: translateX(-50%) scale(1.4); opacity: 0.7; }
}

/* Cards Section */
.cards-section {
  display: flex;
  justify-content: center;
  gap: 20px;
  padding: 30px 20px;
  background-color: #f8f9fa;
}

.card {
  background: white;
  border-radius: 12px;
  padding: 20px;
  width: 280px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.1);
  text-align: center;
  transition: transform 0.2s ease;
}

.card:hover {
  transform: translateY(-5px);
}

.card-icon {
  font-size: 40px;
  margin-bottom: 15px;
}

.card h3 {
  margin: 10px 0;
  font-size: 1.2em;
}

.card p {
  font-size: 0.95em;
  color: #555;
  margin-bottom: 20px;
}

.card-btn {
  display: inline-block;
  padding: 8px 16px;
  border-radius: 6px;
  background-color: #f3f4f6;
  border: 1px solid #ccc;
  color: black;
  text-decoration: none;
  font-weight: bold;
  transition: background 0.3s ease;
}

.card-btn:hover {
  background-color: #e0e0e0;
}

.disabled {
  opacity: 0.5;
}

.disabled-btn {
  display: inline-block;
  padding: 8px 16px;
  border-radius: 6px;
  background-color: #f3f4f6;
  border: 1px solid #ccc;
  color: #666;
  font-weight: bold;
}

sp_widget.script:
(function() {
  var userEmail = gs.getUser().getEmail();
  gs.info("User Email: " + userEmail, "x_vuram_financia_0");

  // -------------------
  // INDIVIDUAL LOOKUP
  // -------------------
  var grInd = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
  grInd.addQuery('email', userEmail);
  grInd.query();

  if (grInd.next()) {
    var indSysId = grInd.getUniqueValue();
    var forename = grInd.getValue('forename_in_full');
    gs.info("Individual record found. Sys ID: " + indSysId + " | Forename: " + forename, "x_vuram_financia_0");
    data.individual = true;

    // Lookup case by individual reference
    var grCase = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    grCase.addQuery('individual', indSysId);
    grCase.orderByDesc('sys_created_on'); // get latest case if multiple
    grCase.query();

    if (grCase.next()) {
      var custType = grCase.getValue('customer_type');
      gs.info("Case record found. Forename: " + forename + " | Customer Type: " + custType, "x_vuram_financia_0");

      if (custType == "customer" || custType == "individual") {
        data.show_customer = true;
        data.show_entity = false;
        gs.info("Set data.show_customer = true and data.show_entity = false", "x_vuram_financia_0");
      } else if (custType == "entity") {
        data.show_customer = false;
        data.show_entity = true;
        gs.info("Set data.show_customer = false and data.show_entity = true", "x_vuram_financia_0");
      }
    } else {
      gs.info("No case found for individual Sys ID: " + indSysId, "x_vuram_financia_0");
    }
  } else {
    gs.info("No Individual record found for email: " + userEmail, "x_vuram_financia_0");
    data.individual = false;
  }

  // -------------------
  // ENTITY LOOKUP
  // -------------------
  var grEnt = new GlideRecord('x_vuram_financia_0_fcc_kyc_entity_details');
  grEnt.addQuery('email_id', userEmail);
  grEnt.query();

  if (grEnt.next()) {
    var entSysId = grEnt.getUniqueValue();
    var legalName = grEnt.getValue('legal_name');
    gs.info("Entity record found. Sys ID: " + entSysId + " | Legal Name: " + legalName, "x_vuram_financia_0");
    data.entity = true;

    // Lookup case by entity reference
    var grCaseEnt = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    grCaseEnt.addQuery('entity', entSysId); // Correct reference for entity
    grCaseEnt.orderByDesc('sys_created_on'); // latest case
    grCaseEnt.query();

    if (grCaseEnt.next()) {
      var custTypeEnt = grCaseEnt.getValue('customer_type');
      gs.info("Case record found for entity. Legal Name: " + legalName + " | Customer Type: " + custTypeEnt, "x_vuram_financia_0");

      if (custTypeEnt == "entity") {
        data.show_customer = false;
        data.show_entity = true;
        gs.info("Set data.show_customer = false and data.show_entity = true", "x_vuram_financia_0");
      } else if (custTypeEnt == "customer" || custTypeEnt == "individual") {
        data.show_customer = true;
        data.show_entity = false;
        gs.info("Set data.show_customer = true and data.show_entity = false", "x_vuram_financia_0");
      }
    } else {
      gs.info("No case found for entity Sys ID: " + entSysId, "x_vuram_financia_0");
    }
  } else {
    gs.info("No Entity record found for email: " + userEmail, "x_vuram_financia_0");
    data.entity = false;
  }

  // Log final values of flags for debugging
  gs.info("FINAL → show_customer=" + data.show_customer + ", show_entity=" + data.show_entity, "x_vuram_financia_0");

})();
